/// <summary>
/// Extension class for <c>InventTransferLine</c> table
/// </summary>
[ExtensionOf(tablestr(InventTransferLine))]
public final class METInventTransferLine_Extension
{
}

Method.Source:
        /// <summary>
    /// CB754 update underbond based on values of Item
    /// </summary>
    /// <param name = "_dropEstimated">_dropEstimated</param>
    public void insert(NoYes _dropEstimated)
    {
        
        next insert(_dropEstimated);

        this.SysExtensionSerializerMap::postInsert();

        // VM - CB754 - Excise Register start
        InventTransferTable inventTransferTable;
        METInventTransferTableExt metInventTransferTable;

        select firstonly UnderBond from metInventTransferTable
             join RecId, InventLocationIdTo from inventTransferTable
                where metInventTransferTable.InventTransferTable == inventTransferTable.RecId
                        && inventTransferTable.TransferId == this.TransferId;

        if (!metInventTransferTable.UnderBond)
        {
            METInventTable metInventTable;
            metTariffItemCodeBase metTariffItemCodeBase;

            select firstonly METTariffItemCodeBaseRecid from metInventTable
                where metInventTable.ItemId == this.ItemId
                exists join metTariffItemCodeBase
                where metTariffItemCodeBase.RecId == metInventTable.METTariffItemCodeBaseRecid;

            if (metInventTable.RecId)
            {
                ttsbegin;
                metInventTransferTable.selectForUpdate(true);
                metInventTransferTable.UnderBond = NoYes::Yes;
                metInventTransferTable.InternalCustomer = METInventLocation::findByInventLocationId(inventTransferTable.InventLocationIdTo).LocalInternalCustomer;
                metInventTransferTable.update();
                ttscommit;
            }
        }
        // VM - CB754 - Excise Register end
    }

/// <summary>
/// Get the warehouse category.
/// </summary>
/// <returns>Warehouse category</returns>
[SysClientCacheDataMethodAttribute(true)]
public display METFilterCodeone displayMETFilterCodeOne()
{
    return InventTable::metGetFilterCodeOne(this.ItemId, this.inventDim().InventSiteId);
}

    /// <summary>
    ///    Called by the kernel when a field on the table has its value modified.
    /// </summary>
    /// <param name="_fieldId">
    ///    The field ID of the field that changed.
    /// </param>
    /// <remarks>
    ///    Methods that should be called when a field value changes are called in this method.
    /// </remarks>
    public void modifiedField(FieldId _fieldId)
    {
        next modifiedField(_fieldId);

        switch (_fieldId)
        {
            case fieldNum(InventTransferLine, ItemId):
                this.setDefaultBatch();
                
            case fieldNum(InventTransferLine, UnitId):
            case fieldNum(InventTransferLine, InventDimId):
                this.metInventTransferLine().updateUnitFields();
                break;
                
        }
    }

    /// <summary>
    /// Get order extract status
    /// </summary>
    /// <returns>METOrderExtractStatus</returns>
    public display METOrderExtractStatus displayOrderExtractStatus()
    {
        METInventTransferLine       metInventTransferLine;

        select firstonly OrderExtractStatus from metInventTransferLine
            where metInventTransferLine.InventTransferLine == this.RecId;

        return metInventTransferLine.OrderExtractStatus;
    }

    /// <summary>
    /// Checks and updates transfer line marking.
    /// </summary>
    public void metCheckAndUpdateMarking(InventTransId _salesLineTransId = '')
    {
        if (!PdsGlobal::pdsIsCWItem(this.ItemId))
        {
            ttsbegin;

            if (!_salesLineTransId)
            {
                _salesLineTransId = this.metInventTransferLine().SalesLineTransId;
            }

            SalesLine salesLine = SalesLine::findInventTransId(_salesLineTransId);

            if (!salesLine.RecId)
            {
                return;
            }

            InventTransOriginId salesLineTransOriginId    = InventTransOrigin::findByInventTransId(_salesLineTransId).RecId;
            InventTransOriginId transferLineTransOriginId = InventTransOrigin::findByInventTransId(this.InventTransIdReceive).RecId;
 
            InventDimParm inventDimParm;
            InventDim     inventDim = salesLine.inventDim();
            inventDimParm.initFromInventDim(inventDim);
 
            this.metUpdateMarking(salesLineTransOriginId, transferLineTransOriginId, - this.QtyTransfer, - this.PdsCWQtyTransfer, inventDim, inventDimParm);
            
            ttscommit;
        }
    }

    /// <summary>
    /// Updates marking.
    /// </summary>
    /// <param name = "_inventTransOriginId">Line to be marked.</param>
    /// <param name = "_markingRefInventTransOriginId">Reference line for marking.</param>
    /// <param name = "_markQty">Qty.</param>
    /// <param name = "_cwMarkQty">CW Qty.</param>
    /// <param name = "_inventDimCriteria">Dimension criteria.</param>
    /// <param name = "_inventDimParm">Dimension parm.</param>
    public void metUpdateMarking(
        InventTransOriginId     _inventTransOriginId,           // Issue
        InventTransOriginId     _markingRefInventTransOriginId, // Receipt
        InventQty               _markQty,
        PdsCWInventQty          _cwMarkQty,
        InventDim               _inventDimCriteria = null,
        InventDimParm           _inventDimParm = null)
    {
        PmfQtyDataCarrier outQuantities = new PmfQtyDataCarrier();
 
        InventQty markedQty = InventTransOrigin::updateMarking(_inventTransOriginId, _markingRefInventTransOriginId, _markQty, '', SortOrder::Descending, true, _inventDimCriteria, _inventDimParm, _cwMarkQty, outQuantities);
 
        if (!markedQty)
        {
            return;
        }
 
        InventQty markedReverseQty = InventTransOrigin::updateMarking(_markingRefInventTransOriginId, _inventTransOriginId, markedQty, '', SortOrder::Descending, true, _inventDimCriteria, _inventDimParm, outQuantities.parmCwQty());
 
        if (markedReverseQty)
        {
            // update reservation for the issue.
            InventUpd_Reservation::updateReserveRefTransId(InventTransOrigin::find(_inventTransOriginId).inventMovement(InventDirection::Issue), true);
        }

    }

    /// <summary>
    /// Reduce the Ship Remain qty to match what was pickied
    /// </summary>
    /// <param name = "_pickingRouteId">Picking route id</param>
    public static void METAdjustShipRemain(WMSPickingRouteID _pickingRouteId)
    {
        WMSOrderTrans               metWMSOrderTrans;
        InventTransferLine          metInventTransferLine;
        METInventTransferLine       metInventTransferLineUpdate;

        if(!METInventTransferTableExt::isAllowBackorderRouteId(_pickingRouteId))
        {
            while select forupdate metInventTransferLine
                join qty, PdsCWQty from metWMSOrderTrans
                where   metInventTransferLine.InventTransId == metWMSOrderTrans.inventTransId
                &&      metInventTransferLine.transferId    == metWMSOrderTrans.inventTransRefId
                &&      metWMSOrderTrans.routeId            == _pickingRouteId
                &&      metWMSOrderTrans.inventTransType    == InventTransType::TransferOrderShip
            {
                if (pdsGlobal::pdsIsCWItem(metInventTransferLine.ItemId))
                {
                    metInventTransferLine.PdsCWQtyRemainShip = metWMSOrderTrans.PdsCWQty;
                }

                metInventTransferLine.QtyRemainShip = metWMSOrderTrans.qty;

                if (metInventTransferLine.validateWrite())
                {
                    metInventTransferLine.updateDeliverRemainder(); //std code contains ttsbegin and ttscommit
                }
                metInventTransferLineUpdate = metInventTransferLine.metInventTransferLine();
                metInventTransferLineUpdate.updateExtractionStatus(METOrderExtractStatus::Extracted);

            }
        }
    }

/// <summary>
/// Get the Invent Transfer Table Ext
/// </summary>
/// <returns>Invent Transfer Table Ext</returns>
public METInventTransferLine metInventTransferLine()
{
    return this.SysExtensionSerializerMap::getExtensionTable(tableNum(METInventTransferLine));
}

    /// <summary>
    /// Method to set default batch on transfer line if batch dimension is active for the item and batch is not provided. This is required as batch is mandatory for PDS items.
    /// </summary>
    public void setDefaultBatch()
    {
        InventDim inventDim = InventDim::find(this.InventDimId);

        if (inventDim.inventBatchId == '')
        {
            InventBatch inventBatch = InventBatch::findOrCreate(METConstants::defaultval, this.ItemId);
            inventDim.inventBatchId = inventBatch.inventBatchId;
            this.InventDimId = InventDim::findOrCreate(inventDim).InventDimId;
        }
    }

    /// <summary>
    /// pack the Invent Transfer Table Ext
    /// </summary>
    /// <param name = "_metInventTransferLine">METInventTransferLine to pack.</param>
    /// <param name = "_skipInit">
    /// CB395_CSDFulfilementInterBranchTransfer.
    /// Introduced this parameter to stop pack method from initializing values.
    /// Kept it as an optional argument to not break the existing processes.
    /// CB395_CSDFulfilementInterBranchTransfer.
    /// </param>
    public void metPackMETInventTransferLine(METInventTransferLine  _metInventTransferLine, boolean _skipInit = false)
    {
        _metInventTransferLine.InventTransferLine = this.RecId;

        if (!_skipInit)
        {
            _metInventTransferLine.initValue();
        }

        this.SysExtensionSerializerMap::packExtensionTable(_metInventTransferLine);
    }

    /// <summary>
    /// Updates a record in the database.
    /// </summary>
    /// <param name="_parameters">
    /// Either a <c>InventTransferLineUpdateParameters</c> instance or (for backwards compatibility) a <c>NoYes</c> value to drop estimated data; optional.
    /// </param>
    /// <param name="_updateHeader">
    /// Indicates whether the header record must be updated; optional. This is only applicable when the first parameter is a <c>NoYes</c> value.
    /// </param>
    /// <remarks>
    /// If the <paramref name="_updateHeader" /> parameter is set to the <c>NoYes::Yes</c> enumeration
    /// value, the estimated transactions related to the line are not updated.
    /// </remarks>
    public void update(
        anytype _parameters ,
        NoYes _updateHeader)
    {
        next update(_parameters, _updateHeader);

        this.SysExtensionSerializerMap::postUpdate();;
    }
